// This file is generated by AI.

// 编辑器行号旁的实时预览指示器 (Monaco glyph margin)。
//
// 风格对齐 VS Code 的调试模式: **实心箭头踩在所在行上**, 并且整行带淡色高亮 ——
// 一眼就能看出"预览现在停在哪一行", 与调试器停在断点上是一样的读法。
//
// 四种状态各画成一个图标, 全部由 CSS 提供 (见 styles.css):
// * 等待中: 中性色箭头 —— "预览正指向这一行";
// * 已执行: 箭头变绿 —— "这一行已经跑完";
// * 已越过: 箭头变黄 —— 预览已经不在这一行上了 (引擎自己走过去了, 或者用户在预览里
//   点去了别处), 不当作错误;
// * 未能执行: 箭头变红并加一道斜杠 —— 快进超时, 点一下可以重跑。
//
// 这里只做渲染与交互, 状态本身在 `preview/live-preview.ts` 里演化。图标放行号**右侧的
// 字形栏** (glyph margin) 而不是行号左侧的差异色块栏: 两者是 Monaco 里并排独立的两栏,
// 各画各的, 不会互相顶掉 (git 差异色块用的是 `linesDecorationsClassName`)。

// 只用类型: 装饰区间用字面量构造, 因此这个模块没有 `monaco-editor` 的运行时依赖。
import type * as monaco from 'monaco-editor';

import type { LivePreviewMarker } from '../preview/live-preview';
import { blockGlyphClassName } from './block-glyph';

type LivePreviewPhase = LivePreviewMarker['phase'];

/**
 * 构造装饰区间。
 *
 * 用字面量而不是 `new monaco.Range(...)`: `IRange` 是结构化接口, 字面量完全够用 ——
 * 这样这个模块就没有 `monaco-editor` 的**运行时**依赖 (只剩类型), 于是它可以在没有
 * Monaco 的测试环境里直接跑 (见 `tests/live-preview-gutter.test.ts`)。
 */
function lineRange(startLineNumber: number, startColumn: number, endLineNumber: number, endColumn: number) {
  return { startLineNumber, startColumn, endLineNumber, endColumn };
}

const PHASE_GLYPH_CLASS: Record<LivePreviewPhase, string> = {
  executing: 'live-preview-glyph-executing',
  done: 'live-preview-glyph-done',
  passed: 'live-preview-glyph-passed',
  failed: 'live-preview-glyph-failed',
};

/** 整行高亮的类名 (与图标同色, 深浅色在 CSS 里各有一套) */
const LINE_PHASE_CLASS: Record<LivePreviewPhase, string> = {
  executing: 'live-preview-line-executing',
  done: 'live-preview-line-done',
  passed: 'live-preview-line-passed',
  failed: 'live-preview-line-failed',
};

/** 各状态的提示文案 (鼠标停在图标上时显示) */
const PRESENTATION: Record<LivePreviewPhase, (line: number, canReplay: boolean) => string> = {
  executing: (line) => `实时预览正指向第 ${line} 行，等待执行完成。`,
  done: (line) => `实时预览已执行到第 ${line} 行。`,
  passed: (line, canReplay) =>
    canReplay
      ? `实时预览没有停在第 ${line} 行（这一句属于连续执行或多行语句，也可能你已在预览里点去了别处）。点击可重新执行这一行。`
      : `实时预览没有停在第 ${line} 行（这一句属于连续执行或多行语句，也可能你已在预览里点去了别处）。`,
  failed: (line, canReplay) =>
    canReplay
      ? `实时预览没有执行到第 ${line} 行（快进超时或被演出阻塞）。点击可重新执行这一行。`
      : `实时预览没有执行到第 ${line} 行（快进超时或被演出阻塞）。预览未连接，暂时无法重新执行。`,
};

interface LivePreviewGutterControllerOptions {
  editor: monaco.editor.IStandaloneCodeEditor;
  /** 当前应当显示的指示器 (null = 不显示) */
  getMarker: () => LivePreviewMarker | null;
  /** 预览是否已连接 —— 未连接时"未能执行"只是提示, 点了也不会重跑 */
  isReplayAvailable: () => boolean;
  /** 点击"未能执行"/"已越过"的图标时重跑这一行 */
  onReplay: (line: number) => void;
}

export function createLivePreviewGutterController(options: LivePreviewGutterControllerOptions) {
  const { editor } = options;
  const decorations = editor.createDecorationsCollection();

  function clear() {
    if (decorations.length === 0) return;
    decorations.clear();
  }

  function sync() {
    const marker = options.getMarker();
    const model = editor.getModel();
    if (!marker || !model) {
      clear();
      return;
    }

    // 文档可能被别处改短, 夹到实际行数内, 避免装饰落在不存在的行上
    const line = Math.min(Math.max(marker.line, 1), Math.max(1, model.getLineCount()));
    const hover = PRESENTATION[marker.phase](marker.line, options.isReplayAvailable());
    decorations.set([
      /*
       * 图标与整行高亮是两条装饰, 这是为了自动换行:
       *
       * * 整行高亮走 `isWholeLine`, 一条长语句折成几行时**每一行都该有底色**(它本来就是
       *   一整行);
       * * 图标只走一个零长度区间。零长度区间落在第一行第一个字符上, Monaco 因此只在
       *   **第一个视觉行**画一次图标 —— 用 `isWholeLine` 的话字形栏会被折出来的每一行
       *   各画一个箭头。
       */
      {
        range: lineRange(line, 1, line, 1),
        options: {
          glyphMarginClassName: blockGlyphClassName(PHASE_GLYPH_CLASS[marker.phase]),
          glyphMarginHoverMessage: { value: hover },
        },
      },
      {
        range: lineRange(line, 1, line, model.getLineMaxColumn(line)),
        options: {
          className: LINE_PHASE_CLASS[marker.phase],
          isWholeLine: true,
        },
      },
    ]);
  }

  function isOwnGlyph(target: monaco.editor.IEditorMouseEvent['target']): boolean {
    const element = target.element as HTMLElement | null;
    return Boolean(element?.classList?.contains('editor-block-glyph'));
  }

  const mouseDownSub = editor.onMouseDown((event) => {
    if (!event.event.leftButton || !isOwnGlyph(event.target)) return;

    const marker = options.getMarker();
    // 还在等待时不响应: 这时点它没有额外含义, 而重复发同步只会打断正在进行的那次
    if (!marker || marker.phase === 'executing' || !options.isReplayAvailable()) return;

    // 用事件里的行号而不是 marker.line: 状态与画面之间可能差一帧, 画在哪一行就重跑哪一行
    options.onReplay(event.target.position?.lineNumber ?? marker.line);
  });

  /*
   * 文档被替换 (场景卡 ↔ 配音卡共用同一份 model, 外部回灌也会改它) 时装饰会被 Monaco 清掉,
   * 这里重新画一次。内容变化不影响已经画好的指示器, 因此不需要重新计算状态。
   */
  const contentSub = editor.onDidChangeModelContent(() => sync());

  return {
    sync,
    dispose() {
      mouseDownSub.dispose();
      contentSub.dispose();
      clear();
    },
  };
}
